const input = $input.first().json || {};
const ctx = { ...input };
function status(res) { return res && res.statusCode !== undefined ? res.statusCode : res && res.status; }
if (input.text && String(input.text).trim().length >= 40) {
  ctx.text = String(input.text).trim();
} else if (input.base64Image) {
  if ($env.PLANNER_OCR_URL) {
    const res = await $http.request({
      method: 'POST',
      url: $env.PLANNER_OCR_URL,
      headers: { 'Content-Type': 'application/json' },
      body: { base64Image: input.base64Image, mimeType: input.mimeType || 'image/png' }
    });
    if (status(res) >= 400) { throw new Error('OCR endpoint returned status ' + status(res)); }
    ctx.text = String((res.body && res.body.text) || '').trim();
  } else {
    throw new Error('No text provided and no PLANNER_OCR_URL configured. Send OCR text from the backend, or configure an OCR endpoint.');
  }
} else {
  throw new Error('Calendar upload requires text (or base64Image with a configured PLANNER_OCR_URL)');
}
if (!ctx.text || ctx.text.trim().length < 40) { throw new Error('OCR produced too little text to parse an academic calendar'); }
if (ctx.text.length > 12000) { ctx.text = ctx.text.slice(0, 12000); }
ctx.fileName = input.fileName || 'calendar';
return [{ json: ctx }];

